import{_ as t,o as r,c as o,aN as e}from"./chunks/framework.D31DlcCL.js";const s="/img/math-matchstick-2.svg",d=JSON.parse('{"title":"奥数进阶：火柴棒（二）图形变换与面积守恒","description":"移动两根火柴，让 3 个三角形变成 5 个？火柴棒进阶题将挑战你的空间重组能力。本文教你如何利用“公用边”实现图形的高效变幻。","frontmatter":{"title":"奥数进阶：火柴棒（二）图形变换与面积守恒","date":"2026-02-18T11:00:00.000Z","categories":["数学"],"tags":["小学奥数","火柴棒问题","几何变换","空间想象"],"description":"移动两根火柴，让 3 个三角形变成 5 个？火柴棒进阶题将挑战你的空间重组能力。本文教你如何利用“公用边”实现图形的高效变幻。","cover":"/img/math-matchstick-2.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-olympiad-matchstick-puzzles-2.md","filePath":"posts/primary-math-olympiad-matchstick-puzzles-2.md","lastUpdated":null}'),i={name:"posts/primary-math-olympiad-matchstick-puzzles-2.md"};function l(n,a,h,c,m,g){return r(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="奥数进阶-火柴棒-二-图形变换与面积守恒" tabindex="-1">奥数进阶：火柴棒（二）图形变换与面积守恒 <a class="header-anchor" href="#奥数进阶-火柴棒-二-图形变换与面积守恒" aria-label="Permalink to &quot;奥数进阶：火柴棒（二）图形变换与面积守恒&quot;">​</a></h1><p>在掌握了火柴棒数字变换后，真正的挑战来了——<strong>图形变换</strong>。</p><p>不同于数字题，图形题要求你不仅要动脑，还要在大脑里进行“拼图游戏”。如何用最少的火柴拼出最多的图形？秘诀就藏在**“公用边”**里。</p><hr><h2 id="一、-核心法宝-公用边的威力" tabindex="-1">一、 核心法宝：公用边的威力 <a class="header-anchor" href="#一、-核心法宝-公用边的威力" aria-label="Permalink to &quot;一、 核心法宝：公用边的威力&quot;">​</a></h2><p>为什么 4 根火柴只能摆 1 个正方形，而 7 根火柴却能摆 2 个？</p><p><img src="'+s+'" alt="火柴棒图形变换示意图"></p><p>因为中间的那根火柴被两个正方形<strong>公用</strong>了！</p><ul><li><strong>规律</strong>：公用边越多，节省的火柴就越多，能拼出的图形就越多。</li></ul><hr><h2 id="二、-实战技巧解析" tabindex="-1">二、 实战技巧解析 <a class="header-anchor" href="#二、-实战技巧解析" aria-label="Permalink to &quot;二、 实战技巧解析&quot;">​</a></h2><h3 id="_1-移动与重组" tabindex="-1">1. 移动与重组 <a class="header-anchor" href="#_1-移动与重组" aria-label="Permalink to &quot;1. 移动与重组&quot;">​</a></h3><p><strong>【例题 1】</strong>：如下图所示，用 12 根火柴摆成了 4 个正方形。移动 2 根，变成 7 个正方形。 <em>(假设是一个大田字格)</em><strong>解析</strong>： 很多同学会觉得 12 根火柴怎么可能摆出 7 个？ <strong>技巧</strong>：想办法制造出“大中有小”的重叠结构。</p><ol><li>移动外围的两根。</li><li>将它们放到大正方形内部形成交叉。 <strong>结果</strong>：你得到了 4 个小正方形 + 1 个中正方形 + 1 个大正方形……通过巧妙的重叠，数量会大幅增加。</li></ol><h3 id="_2-去掉火柴减图形" tabindex="-1">2. 去掉火柴减图形 <a class="header-anchor" href="#_2-去掉火柴减图形" aria-label="Permalink to &quot;2. 去掉火柴减图形&quot;">​</a></h3><p><strong>【例题 2】</strong>：用火柴摆出一个 3×3 的网格（共 9 个小格）。去掉 3 根，让它只剩下 3 个正方形。 <strong>解析</strong>： 这需要打破原来的对称，尽量破坏掉那些小格子的边界。</p><hr><h2 id="三、-进阶技巧-面积守恒与变化" tabindex="-1">三、 进阶技巧：面积守恒与变化 <a class="header-anchor" href="#三、-进阶技巧-面积守恒与变化" aria-label="Permalink to &quot;三、 进阶技巧：面积守恒与变化&quot;">​</a></h2><ul><li><strong>移动</strong>：总火柴数不变，周长可能不变，但面积往往会变。</li><li><strong>目标</strong>：题目问“增加面积”还是“减少形状”？</li><li><strong>策略</strong>：把外围的火柴移到内部，通常会增加小形状的数量。</li></ul><hr><h2 id="四、-避坑指南-不要留下-断头线" tabindex="-1">四、 避坑指南：不要留下“断头线” <a class="header-anchor" href="#四、-避坑指南-不要留下-断头线" aria-label="Permalink to &quot;四、 避坑指南：不要留下“断头线”&quot;">​</a></h2><ul><li><strong>规则</strong>：拼出的图形必须是闭合的、规范的。</li><li><strong>警示</strong>：如果剩下半截火柴悬在空中，那是不符合题目要求的。</li></ul><hr><h2 id="五、-练一练-图形魔术师" tabindex="-1">五、 练一练（图形魔术师） <a class="header-anchor" href="#五、-练一练-图形魔术师" aria-label="Permalink to &quot;五、 练一练（图形魔术师）&quot;">​</a></h2><ol><li><strong>基础关</strong>：用 6 根火柴摆出 2 个等边三角形。（提示：利用公用边）</li><li><strong>进阶关</strong>：用 9 根火柴摆出 3 个等边三角形。</li><li><strong>挑战关</strong>：用 12 根火柴摆出 6 个等边三角形。（提示：考虑立体图形！）</li></ol><hr><p><em>总结：火柴棒图形题是空间思维的终极训练。记住“公用边”和“重叠法”，你就能在有限的线条中创造无限的可能！</em></p>',27)])])}const u=t(i,[["render",l]]);export{d as __pageData,u as default};
